head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > M > addTab]<br/>TabControl 컴포넌트에 동적으로 새로운 Tab 페이지를 추가합니다.",
    "validation" : [
        "addTab() 은 비동기 메소드이므로 async/await 로 처리해야 합니다.",
        "id(필수) 파라미터로 추가하는 Tab 페이지의 ID 를 설정합니다.",
        "tabOptions(필수) 파라미터로 추가하는 Tab 페이지의 Tabs 생성 옵션을 정의합니다.",
        "contentOptions(필수) 파라미터로 추가하는 Tab 페이지의 Content 생성 옵션을 정의합니다.",
        "addTab() 메소드로 Tab 페이지 추가 시 Content 를 직접 정의할 수 없으며 src 속성으로 XML 화면을 로딩해야 합니다.",
        "TabControl 컴포넌트에 정의된 Tab 페이지 갯수가 windowMaxNum 속성값에 도달한 경우 Tab 페이지가 추가되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        alwaysDraw : true,
        windowMaxNum : 3,
    }

    let cList= $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';    
    strTarget += '<w2:content src="/sample/common_link/tabControl_link_1.xml" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';    
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.btn_getTabInfo_onclick = function (rtn) {      
    let arrTabInfo = target1.getTabInfo();    

    for (var i=0; i < arrTabInfo.length; i++) {     
        if (arrTabInfo[i].id == rtn) {
            wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].id : " + arrTabInfo[i].id);    
            wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].label : " + arrTabInfo[i].label);    
            wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].defaultTabIndex : " + arrTabInfo[i].defaultTabIndex);    
            wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].currentTabIndex : " + arrTabInfo[i].currentTabIndex);    
            wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].src : " + arrTabInfo[i].src);    
            wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].alwaysDraw : " + arrTabInfo[i].alwaysDraw); 

            target1.setSelectedTabIndex(arrTabInfo[i].id);
        }      
    }       
}



scwin.btn_addTab_onclick = async function (e) {
    let tabCount = target1.getTabCount();

    let id = "tabs" + (tabCount+1);

     var rowJSON = {
        "Personal Info" : { "Name": "Lee", "Age": 50, "Married" : false},   
        "Region": "Seoul",  
        "Carrier": true,
    }; 

    let rtn = await target1.addTab(id,  
        {   
            "label": id, 
            "title": "dataObject", 
            "openAction": "exist",
            "closable": "true"                       
        }, 
        {   
            "src": "/sample/common_link/tabControl_addTab_1.xml",
            "frameMode" : "wframePreload",
            "scope" : true, 
            "alwaysDraw": true,
            "dataObject":{
                "type" : "json",
                "name" : "tabParam",
                "data" : rowJSON
            }
        }
    );

    scwin.btn_getTabInfo_onclick(rtn);
};
